for(const status of ['completed','draft'])check(`${status} review document is readonly with correct Edit availability`,h=>{let edits=0;const row={...review,status,manager_review:'Synthetic manager feedback',rating:'4'},vm={...ready(h,{mode:'review',resourceValue:{...resources,self:{...self,performance:[row]}}}),openReviewEditor:()=>edits++},tree=h.component(registerFile,'SelfReviewDocument',{vm});assert.equal(nodes(tree,'form').length+nodes(tree,'textarea').length+nodes(tree,'input').length,0);assert.match(text(tree),/Synthetic manager feedback/);const buttons=nodes(tree,'button');assert.equal(buttons.length,status==='completed'?0:1);if(buttons.length){buttons[0].props.onClick();assert.equal(edits,1);}else assert.match(text(tree),/completed and locked/);});
check('denied access and unavailable/completed review show no save form',h=>{const vm=ready(h,{mode:'review_edit'});for(const patch of [{canHR:false},{resources:{...resources,self:null}},{review:null},{review:{...review,status:'completed'}}]){const tree=h.component(editorFile,'SelfServiceEditor',{vm:{...vm,...patch}});assert.equal(nodes(tree,'form').length,0);assert.equal(nodes(tree,'SelfState').length,1);}});
check('mobile section select preserves exactly the same seven choices and busy guard as desktop tabs',h=>{const changes=[],vm={...ready(h),changeBrowse:value=>changes.push(value)},tree=h.component(registerFile,'SelfSectionNav',{vm}),select=nodes(tree,'select')[0],tabs=nodes(tree,'button');assert.deepEqual(nodes(select,'option').map(o=>o.props.value),['overview','attendance','leave','records','reviews','pay','policies']);assert.equal(tabs.length,7);select.props.onChange({target:{value:'attendance'}});tabs[2].props.onClick();assert.deepEqual(changes,[{view:'attendance'},{view:'leave'}]);const busy=h.component(registerFile,'SelfSectionNav',{vm:{...vm,busy:true}});assert.ok(nodes(busy,'button').every(b=>b.props.disabled));assert.equal(nodes(busy,'select')[0].props.disabled,true);});
check('day off suppresses check-in but keeps overnight checkout usable with explicit context',h=>{const actions=[],vm={...ready(h,{resourceValue:{...resources,plan:{...plan,mode:'off'}}}),attendanceAction:kind=>actions.push(kind)},tree=h.component(registerFile,'WorkdayPanel',{vm}),buttons=nodes(tree,'button');assert.equal(buttons[0].props.disabled,true);assert.equal(buttons[1].props.disabled,false);buttons[1].props.onClick();assert.deepEqual(actions,['check-out']);assert.match(text(tree),/open overnight shift/);assert.match(text(tree),/refresh.*before retrying/);});
for(const [mode,phrase]of [['office','precise browser location'],['remote','location is not requested'],['field','GPS is not requested']])check(`${mode} attendance clearly distinguishes location policy without implicit location lookup`,h=>{const vm=ready(h,{resourceValue:{...resources,plan:{...plan,mode}}}),tree=h.component(registerFile,'WorkdayPanel',{vm});assert.match(text(tree),new RegExp(phrase));assert.equal(h.gpsCalls.length,0);assert.equal(h.requests.length,0);});
check('monthly calendar exposes original minutes/status totals and controlled URL month without treating missing as absent',h=>{const changes=[],vm={...ready(h),changeBrowse:value=>changes.push(value)},tree=expand(h.component(registerFile,'AttendanceRegister',{vm})),month=nodes(tree,'input').find(n=>n.props.type==='month');month.props.onChange({target:{value:'2026-11'}});assert.deepEqual(changes,[{month:'2026-11'}]);assert.match(text(tree),/Missing records are not counted as absence/);assert.match(text(tree),/128h/);assert.match(text(tree),/Overtime1h/);assert.match(text(tree),/Work 8h/);});
check('leave balances stay typed ledger values and only pending rows expose Cancel',h=>{const calls=[],vm={...ready(h,{resourceValue:{...resources,self:{...self,leave_requests:[leave,{...leave,id:'approved',status:'approved'}]}}}),cancelLeave:id=>calls.push(id)},tree=expand(h.component(registerFile,'LeaveRegister',{vm})),buttons=nodes(tree,'button').filter(n=>text(n)==='Cancel request');assert.equal(buttons.length,1);buttons[0].props.onClick();assert.deepEqual(calls,[leave.id]);assert.match(text(tree),/Allowance20Approved3Pending2Remaining15/);assert.match(text(tree),/Latest 50 requests/);});
check('private document file route remains proxy-mediated and never trusts external raw file URL',h=>{const vm=ready(h,{resourceValue:{...resources,self:{...self,documents:[{...self.documents[0],id:'doc/one',file_url:'https://untrusted.invalid/file'},{...self.documents[0],id:'nofile',file_url:null}]}}}),tree=h.component(registerFile,'DocumentsRegister',{vm}),links=nodes(tree,'a');assert.equal(links.length,1);assert.equal(links[0].props.href,'/api/hr-documents/self/doc%2Fone/file');assert.equal(links[0].props.target,'_blank');assert.match(text(tree),/No file/);});
check('payslip rows retain each native currency and exact personal entry destination',h=>{const vm=ready(h,{resourceValue:{...resources,self:{...self,payslips:[self.payslips[0],{...self.payslips[0],entry_id:'usd/entry',currency:'USD',gross_pay:'50.00',net_pay:'40.00'}]}}}),tree=expand(h.component(registerFile,'PayslipRegister',{vm}));assert.deepEqual(nodes(tree,'NextLink').map(n=>n.props.href),['/dashboard/hr/me/payslips/syn-entry','/dashboard/hr/me/payslips/usd%2Fentry']);assert.match(text(tree),/BDT 1,100.00/);assert.match(text(tree),/USD 40.00/);assert.match(text(tree),/Latest 24/);});
check('policy list offers one policy acknowledgement, no announcement mutation, and fails closed if acknowledgement state missing',h=>{const calls=[],vm={...ready(h),acknowledge:id=>calls.push(id)},tree=h.component(registerFile,'PoliciesRegister',{vm}),buttons=nodes(tree,'button');assert.equal(buttons.length,1);buttons[0].props.onClick();assert.deepEqual(calls,[policy.id]);const unknown=h.component(registerFile,'PoliciesRegister',{vm:{...vm,resources:{...resources,acks:null}}});assert.equal(nodes(unknown,'button')[0].props.disabled,true);const saved=h.component(registerFile,'PoliciesRegister',{vm:{...vm,resources:{...resources,acks:{[policy.id]:'2026-10-26T03:00:00Z'}}}});assert.equal(nodes(saved,'button').length,0);assert.match(text(saved),/Acknowledged/);});
for(const permission of ['hr.self','projects.work'])check(`Employee home ${permission}-only access does not leak the other capability's sections`,h=>{h.permissions([permission]);const vm=ready(h,{mode:'home'}),tree=h.component(homeFile,'EmployeeHome',{vm}),copy=text(tree);if(permission==='hr.self'){assert.equal(nodes(tree,'WorkdayPanel').length,1);assert.doesNotMatch(copy,/Synthetic task|Synthetic project|Assigned110/);}else{assert.equal(nodes(tree,'WorkdayPanel').length,0);assert.doesNotMatch(copy,/Latest net pay|Synthetic announcement|Request leave/);assert.match(copy,/Synthetic task/);}});
check('Employee home priorities cap display only, preserving authoritative counts and task/project links',h=>{const tasks=Array.from({length:8},(_,i)=>({...task,id:'task-'+i,title:'Priority '+i,due_date:'2026-10-'+String(18+i).padStart(2,'0')})),projects=Array.from({length:9},(_,i)=>({...work.projects[0],id:'project-'+i})),vm=ready(h,{mode:'home',resourceValue:{...resources,work:{...work,tasks,projects}}}),tree=expand(h.component(homeFile,'EmployeeHome',{vm})),links=nodes(tree,'NextLink');assert.equal(links.filter(n=>n.props.href.startsWith('/dashboard/my-work/tasks/')).length,5);assert.equal(links.filter(n=>/^\/dashboard\/projects\/project-/.test(n.props.href)).length,6);assert.match(text(tree),/Assigned110/);assert.match(text(tree),/Summary counts cover all assigned open work/);assert.match(text(tree),/limit 100/);assert.match(text(tree),/limit 50/);});
check('Employee home work read failure keeps verified HR available and never invents empty work counts',h=>{const vm=ready(h,{mode:'home',resourceValue:{...resources,work:null}}),tree=expand(h.component(homeFile,'EmployeeHome',{vm}));assert.match(text(tree),/Work summary unavailable/);assert.match(text(tree),/BDT 1,100.00/);assert.doesNotMatch(text(tree),/Assigned0/);});
check('committed editor renders recovery-only result, not another writable form or submit',h=>{ready(h,{mode:'leave',values:leaveValues});h.set('committed',true);const tree=expand(h.component(workspaceFile,'SelfServiceContent'));assert.match(text(tree),/Your change was saved/);assert.match(text(tree),/Do not submit/);assert.equal(nodes(tree,'form').length,0);const saved=nodes(tree,'button').find(n=>text(n).includes('Open saved result'));assert.ok(saved);saved.props.onClick();assert.equal(h.navigation[0][0],'navigate');assert.deepEqual(h.navigation[0][2],{discard:true,replace:true});assert.equal(h.requests.length,0);});
check('initial workspace loading is announced and cannot expose an empty editable form',h=>{h.render();const tree=expand(h.component(workspaceFile,'SelfServiceContent'));assert.match(text(tree),/Loading your workspace/);assert.equal(nodes(tree,'form').length,0);assert.ok(nodes(tree,'section').some(n=>n.props.role==='status'));});
check('pending write enables shared HR document busy guard even on a read register',async h=>{const vm=ready(h);let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=vm.attendanceAction('check-out');h.render();const guard=h.guardCalls.at(-1);assert.equal(guard.options.enabled,true);assert.equal(guard.options.documentLabel,'HR request');assert.equal(guard.options.isBusy,true);assert.equal(guard.dirty,false);resolve(fail(409));await pending;});
check('failed section Retry invokes reads only and does not replace retained request input',async h=>{ready(h,{mode:'leave'});await h.api().load(true);h.render().change('reason','Keep this text');h.set('resources',{...resources,self:null});const vm=h.render(),tree=h.component(editorFile,'SelfServiceEditor',{vm}),state=nodes(tree,'SelfState')[0],button=nodes(state.props.action,'button')[0];assert.equal(text(button),'Retry loading');button.props.onClick();await settle();assert.ok(h.requests.every(r=>!r.options?.method));assert.equal(h.render().values.reason,'Keep this text');});
check('editor Cancel navigates through guard only, never invokes a cancel-record mutation',h=>{const vm=ready(h,{mode:'remote',values:remoteValues}),tree=h.component(editorFile,'SelfServiceEditor',{vm}),cancel=nodes(tree,'button').find(n=>text(n)==='Cancel');h.confirm(false);cancel.props.onClick();assert.equal(h.navigation.length,0);assert.equal(h.requests.length,0);assert.deepEqual(h.render().values,remoteValues);});
check('all saved form targets preserve safe month/list context and correct read-only destination',async h=>{const vm=ready(h,{mode:'review_edit',values:reviewValues});h.query('returnTo='+encodeURIComponent('/dashboard/hr/me?view=reviews&month=2026-10'));await h.render().save();const href=h.navigation[0][1];assert.equal(href.split('?')[0],'/dashboard/hr/me/reviews/syn-review');assert.equal(new URLSearchParams(href.split('?')[1]).get('returnTo'),'/dashboard/hr/me?view=reviews&month=2026-10');assert.ok(vm.editing);});
check('field prompt returning after a newer epoch cannot send a stale attendance write',async h=>{let release;const vm=ready(h,{resourceValue:{...resources,plan:{...plan,mode:'office'}}});navigator.geolocation.getCurrentPosition=success=>release=success;const pending=vm.attendanceAction('check-in');await vm.load();release({coords:{latitude:0,longitude:0,accuracy:10},timestamp:1792987200000});await pending;assert.equal(h.requests.filter(r=>r.options?.method).length,0);assert.equal(h.state('message'),null);});
for(const value of [[],['2026-10-26T03:00:00Z']])check('array acknowledgement payload is not a verified ID-to-timestamp record',h=>assert.equal(h.load(path.join(root,modelFile)).isSelfResource('acks',value),false));
check('malformed acknowledgement200 leaves policy actions disabled, not interpreted as nobody acknowledged',async h=>{h.render();h.response((url,options)=>url.includes('policy-acknowledgements')?ok([]):h.defaultResponse(url,options));await h.api().load();const vm=h.render();assert.equal(vm.resources.acks,null);assert.match(vm.readErrors.acks,/could not be verified/);await vm.acknowledge(policy.id);assert.equal(h.requests.filter(r=>r.options?.method).length,0);});
check('unconfigured weekly policy remains supported without inventing a seven-day office schedule',h=>{const m=h.load(path.join(root,modelFile));assert.equal(m.isSelfResource('plan',{...plan,mode:'unconfigured',weekly_modes:null,office_name:null}),true);});
